"""Run against fixtures generated by tests/generate_models.py."""

import gc
import json
import os
from concurrent.futures import ThreadPoolExecutor
from contextlib import nullcontext
from pathlib import Path

import leapp_runtime as lr
import numpy as np
import pytest

FIXTURES = Path(os.environ.get("LEAPP_TRITON_FIXTURES", "target/triton-fixtures"))
BACKENDS = os.environ.get("LEAPP_TRITON_BACKENDS", "/opt/tritonserver/backends")
CUDA = os.environ.get("LEAPP_TEST_CUDA") == "1"


def runtime(name="feedback", device="cpu"):
    return lr.Runtime.open(
        lr.Bundle.open(FIXTURES / f"{name}.yaml"),
        lr.RuntimeOptions(device=device, backend_directory=BACKENDS),
    )


def step(session, value=1, **kwargs):
    return session.run(
        {"accumulator/observation": np.full(4, value, dtype=np.float32)}, **kwargs
    )["accumulator/next"]




def test_read_only_lifetime_feedback_and_close():
    with runtime() as rt:
        session = rt.create_session()
        tensor = step(session)
        view = tensor.numpy()
        assert not view.flags.writeable
        with pytest.raises(ValueError):
            view[0] = 99
        with pytest.raises(ValueError):
            view.setflags(write=True)
        mutable = view.copy()
        mutable[:] = 99
        np.testing.assert_array_equal(step(session).numpy(), [2] * 4)
        np.testing.assert_array_equal(view, [1] * 4)
        session.reset()
        np.testing.assert_array_equal(step(session).numpy(), [1] * 4)
        assert tensor.shape == (4,)
        assert tensor.dtype == "float32"
        assert tensor.device == "cpu"
    rt.close()
    for operation in (
        rt.create_session,
        session.reset,
        lambda session=session: step(session),
    ):
        with pytest.raises(lr.RuntimeError) as error:
            operation()
        assert error.value.code == lr.ErrorCode.INVALID_ARGUMENT
        assert error.value.phase == "execute"
    assert rt.info().model_names() == ["accumulator"]
    del tensor, rt, session
    gc.collect()
    np.testing.assert_array_equal(view, [1] * 4)


def test_dlpack_copy_and_explicit_view():
    torch = pytest.importorskip("torch")
    with runtime() as rt:
        session = rt.create_session()
        tensor = step(session)
        first = torch.from_dlpack(tensor)
        second = torch.from_dlpack(tensor)
        shared = torch.from_dlpack(tensor.dlpack_view())
        original_address = tensor.numpy().__array_interface__["data"][0]
        assert first.data_ptr() != original_address
        assert first.data_ptr() != second.data_ptr()
        assert shared.data_ptr() == original_address
        first.fill_(99)
        np.testing.assert_array_equal(tensor.numpy(), [1] * 4)
        np.testing.assert_array_equal(step(session).numpy(), [2] * 4)
        with pytest.raises(BufferError, match="dlpack_view"):
            tensor.__dlpack__(copy=False)
        # Versioned NumPy consumers must see the explicit shared export as read-only.
        array = np.from_dlpack(tensor.dlpack_view())
        assert not array.flags.writeable
        assert array.__array_interface__["data"][0] == original_address
        copied = np.from_dlpack(tensor)
        assert copied.__array_interface__["data"][0] != original_address
    del tensor, rt, session
    gc.collect()
    assert shared.tolist() == [1] * 4
    assert second.tolist() == [1] * 4


def test_dlpack_inputs_and_validation():
    torch = pytest.importorskip("torch")
    with runtime("dynamic") as rt:
        session = rt.create_session()
        source = torch.arange(8, dtype=torch.float32)
        with pytest.raises(BufferError, match="gradient"):
            session.run({"dynamic/input": source.clone().requires_grad_()})
        # A storage offset in a contiguous tensor is valid.
        np.testing.assert_array_equal(
            session.run({"dynamic/input": source[2:6]}).numpy("dynamic/output"),
            np.arange(2, 6, dtype=np.float32),
        )
        for bad in (np.ones(4, dtype=">f4"),):
            with pytest.raises(BufferError):
                session.run({"dynamic/input": bad})
        with pytest.raises(lr.RuntimeError) as error:
            session.run({"dynamic/input": np.ones(4, dtype=np.int32)})
        assert error.value.code == lr.ErrorCode.INVALID_ARGUMENT
        with pytest.raises(KeyError):
            session.run({"dynamic/input": source})["missing"]
        assert len(session.run({"dynamic/input": source})) == 1
        for shape in (0, 1, 9):
            result = session.run({"dynamic/input": np.ones(shape, dtype=np.float32)})
            assert result["dynamic/output"].shape == (shape,)


def test_serialization_and_concurrent_sessions():
    with runtime() as rt, ThreadPoolExecutor(max_workers=4) as pool:
        session = rt.create_session()
        values = list(pool.map(lambda _: float(step(session).numpy()[0]), range(12)))
        assert sorted(values) == list(range(1, 13))
        sessions = [rt.create_session() for _ in range(4)]
        values = list(pool.map(lambda s: float(step(s).numpy()[0]), sessions))
        assert values == [1] * 4
        future = pool.submit(lambda: [step(session) for _ in range(20)])
        rt.close()
        try:
            future.result(timeout=20)
        except lr.RuntimeError as error:
            assert error.code == lr.ErrorCode.INVALID_ARGUMENT


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("output_device", ["cpu", "pinned", "cuda:0"])
def test_cuda_streams_and_output_placement(output_device):
    cp = pytest.importorskip("cupy")
    torch = pytest.importorskip("torch")
    with runtime(device="cuda:0") as rt:
        session = rt.create_session()
        stream = cp.cuda.Stream(non_blocking=True)
        with stream:
            obs = cp.arange(4, dtype=cp.float32)
            obs += 1
            result = session.run(
                {"accumulator/observation": obs}, output_device=output_device
            )
        tensor = result["accumulator/next"]
        assert tensor.device == output_device
        if output_device == "cuda:0":
            with cp.cuda.Stream(non_blocking=True):
                copied = cp.from_dlpack(tensor)
                shared = cp.from_dlpack(tensor.dlpack_view())
                assert copied.data.ptr != shared.data.ptr
                copied[:] = 99
                np.testing.assert_array_equal(cp.asnumpy(shared), [1, 2, 3, 4])
            with pytest.raises(BufferError):
                tensor.numpy()
            # Check another framework's producer stream handoff.
            torch_stream = torch.cuda.Stream()
            with torch.cuda.stream(torch_stream):
                value = torch.ones(4, dtype=torch.float32, device="cuda")
                value.mul_(2)
                next_result = session.run(
                    {"accumulator/observation": value}, output_device="cuda:0"
                )
            np.testing.assert_array_equal(
                cp.asnumpy(cp.from_dlpack(next_result["accumulator/next"])),
                [3, 4, 5, 6],
            )
        else:
            np.testing.assert_array_equal(tensor.numpy(), [1, 2, 3, 4])
        session.reset()
        result = step(session, output_overrides={"accumulator/next": "cpu"})
        assert result.device == "cpu"




@pytest.mark.parametrize("output_device", ["cpu", "pinned", "cuda:0"])
def test_runtime_tensor_inputs(output_device):
    if output_device != "cpu" and not CUDA:
        pytest.skip("set LEAPP_TEST_CUDA=1")
    with runtime("dynamic") as rt:
        session = rt.create_session()
        result = session.run(
            {"dynamic/input": np.array([7], dtype=np.float32)},
            output_device=output_device,
        )
        retained = result["dynamic/output"]
        assert retained.shape == (1,)
        for _ in range(8):
            result = session.run(
                {"dynamic/input": result["dynamic/output"]},
                output_device=output_device,
            )
            assert result["dynamic/output"].device == output_device
        host = session.run({"dynamic/input": result["dynamic/output"]})
        np.testing.assert_array_equal(host.numpy("dynamic/output"), [7])
        host = session.run({"dynamic/input": retained})
        np.testing.assert_array_equal(host.numpy("dynamic/output"), [7])


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("device", ["cpu", "cuda:0"])
@pytest.mark.parametrize("legacy", [False, True])
def test_pinned_pytorch_input(device, legacy):
    torch = pytest.importorskip("torch")
    source = torch.arange(4, dtype=torch.float32, pin_memory=True)

    class LegacyProducer:
        def __dlpack_device__(self):
            return source.__dlpack_device__()

        def __dlpack__(self, *, stream=None):
            return source.__dlpack__(stream=stream)

    producer = LegacyProducer() if legacy else source
    with runtime("dynamic", device) as rt:
        result = rt.create_session().run({"dynamic/input": producer})
        np.testing.assert_array_equal(result.numpy("dynamic/output"), [0, 1, 2, 3])
    assert source.is_pinned()
    torch.testing.assert_close(source, torch.arange(4, dtype=torch.float32))


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("legacy", [False, True])
@pytest.mark.parametrize("fail", [False, True])
def test_dlpack_selects_producer_device_and_restores_caller(legacy, fail):
    torch = pytest.importorskip("torch")
    if torch.cuda.device_count() < 2:
        pytest.skip("requires two CUDA devices")
    original = torch.cuda.current_device()
    target = (original + 1) % torch.cuda.device_count()
    stream = torch.cuda.Stream(device=target)
    calls = []

    class Producer:
        def __dlpack_device__(self):
            return source.__dlpack_device__()

        def __dlpack__(self, *, stream, max_version=None):
            calls.append(torch.cuda.current_device())
            assert calls[-1] == target
            if legacy and max_version is not None:
                raise TypeError("max_version unsupported")
            if fail:
                raise ValueError("producer failed")
            return source.__dlpack__(stream=stream)

    with runtime("dynamic", f"cuda:{target}") as rt, torch.cuda.stream(stream):
        source = torch.ones(4, dtype=torch.float32, device=f"cuda:{target}")
        source.mul_(3)
        torch.cuda.set_device(original)
        if fail:
            with pytest.raises(ValueError, match="producer failed"):
                rt.create_session().run({"dynamic/input": Producer()})
        else:
            result = rt.create_session().run({"dynamic/input": Producer()})
            np.testing.assert_array_equal(result.numpy("dynamic/output"), [3] * 4)
        assert torch.cuda.current_device() == original
    assert calls == [target] * (2 if legacy else 1)
    assert torch.cuda.current_device() == original


@pytest.mark.parametrize("layout", ["slice", "reverse", "broadcast", "offset", "empty"])
def test_numpy_input_layouts(layout):
    source = np.arange(12, dtype=np.float32)
    views = {
        "slice": source[1::3],
        "reverse": source[::-1],
        "broadcast": np.broadcast_to(source[2:3], (4,)),
        "offset": source[2:6],
        "empty": source[:0],
    }
    value = views[layout]
    with runtime("dynamic") as rt:
        result = rt.create_session().run({"dynamic/input": value})
    np.testing.assert_array_equal(result.numpy("dynamic/output"), value)
    np.testing.assert_array_equal(source, np.arange(12, dtype=np.float32))


@pytest.mark.parametrize("device", ["cpu"] + (["cuda:0"] if CUDA else []))
@pytest.mark.parametrize("layout", ["slice", "broadcast", "offset", "empty"])
def test_pytorch_input_layouts(device, layout):
    torch = pytest.importorskip("torch")
    context = (
        torch.cuda.stream(torch.cuda.Stream(device=device))
        if device.startswith("cuda")
        else nullcontext()
    )
    with runtime("dynamic", device) as rt, context:
        source = torch.arange(12, dtype=torch.float32, device=device)
        source.mul_(3)
        views = {
            "slice": source[1::3],
            "broadcast": source[2:3].expand(4),
            "offset": source[2:6],
            "empty": source[:0],
        }
        value = views[layout]
        result = rt.create_session().run({"dynamic/input": value})
        expected = value.cpu().numpy().copy()
    del views, value
    gc.collect()
    np.testing.assert_array_equal(result.numpy("dynamic/output"), expected)
    torch.testing.assert_close(source.cpu(), torch.arange(12, dtype=torch.float32) * 3)


